package fr.manuel.anime;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Owns transfers independently of the reader Activity. Partial pages are resumed safely. */
public class DownloadService extends Service {
 static class Task {volatile boolean cancel=false;boolean submitted=false;volatile String state="queued",error="";}
 static final ConcurrentHashMap<String,Task> tasks=new ConcurrentHashMap<>();
 final ExecutorService worker=Executors.newSingleThreadExecutor();
 OfflineStore store;String sourceAgent="Mozilla/5.0 (Android)";PowerManager.WakeLock wake;
 final Handler handler=new Handler(Looper.getMainLooper());boolean stopped=false;int lastStart;
 @Override public void onCreate(){super.onCreate();try{store=new OfflineStore(new File(getFilesDir(),"chapters"));}catch(Exception e){stopSelf();return;}sourceAgent=getSharedPreferences("reader",0).getString("agent",sourceAgent);NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("downloads","Téléchargements",NotificationManager.IMPORTANCE_LOW));startForeground(7,notice());wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"LecteurManga:downloads");wake.acquire(6*60*60*1000L);handler.post(ticker);}
 Notification notice(){String title="Téléchargements",text="Préparation des chapitres…";int done=0,total=0;for(Map.Entry<String,Task> entry:tasks.entrySet())if(entry.getValue().state.equals("downloading"))try{JSONObject m=store.status(entry.getKey());title=m.getString("title");done=m.getInt("done");total=m.getInt("pages");text=done+" / "+total+" pages · En arrière-plan";break;}catch(Exception ignored){}PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent pause=PendingIntent.getService(this,1,new Intent(this,DownloadService.class).setAction("pause"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"downloads").setSmallIcon(android.R.drawable.stat_sys_download).setContentTitle(title).setContentText(text).setContentIntent(open).setOnlyAlertOnce(true).setOngoing(true).setProgress(total,done,total==0).addAction(new Notification.Action.Builder(null,"Tout mettre en pause",pause).build()).build();}
 final Runnable ticker=new Runnable(){public void run(){if(stopped)return;getSystemService(NotificationManager.class).notify(7,notice());handler.postDelayed(this,2000);}};
 @Override public int onStartCommand(Intent intent,int flags,int startId){lastStart=startId;if(intent!=null&&"pause".equals(intent.getAction())){for(Task t:tasks.values())t.cancel=true;finishIfIdle();return START_NOT_STICKY;}String id=intent==null?null:intent.getStringExtra("id");if(id==null){finishIfIdle();return START_NOT_STICKY;}Task task=tasks.get(id);if(task==null){task=new Task();tasks.put(id,task);}if(task.submitted)return START_NOT_STICKY;task.submitted=true;final Task transfer=task;worker.execute(()->{runDownload(id,transfer);handler.post(()->finishIfIdle());});return START_NOT_STICKY;}
 void finishIfIdle(){for(Task t:tasks.values())if(t.state.equals("queued")||t.state.equals("downloading"))return;stopSelfResult(lastStart);}
 void runDownload(String id,Task task){try{if(task.cancel)throw new InterruptedIOException();task.state="downloading";JSONObject m=store.meta(id);ChapterDownloader.run(store,m,()->task.cancel,(url,file)->fetchImage(url,file,task));if(task.cancel)throw new InterruptedIOException();JSONObject book=m.optJSONObject("book");String cover=book==null?"":book.optString("image");if(Catalog.imageUrl(cover))try{fetchImage(cover,new File(store.dir(id),"cover.img"),task);}catch(Exception ignored){}task.state="complete";}catch(InterruptedIOException e){task.state="paused";task.error="Téléchargement en pause. Tu peux le reprendre.";}catch(Exception e){task.state="error";task.error=friendly(e);}}
 @Override public void onTimeout(int startId,int type){for(Task t:tasks.values())t.cancel=true;stopSelf();}
 @Override public void onDestroy(){stopped=true;handler.removeCallbacks(ticker);for(Task t:tasks.values())if(t.state.equals("queued")||t.state.equals("downloading"))t.cancel=true;worker.shutdown();if(wake!=null&&wake.isHeld())wake.release();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
 HttpURLConnection connection(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(25000);c.setRequestProperty("User-Agent","Mozilla/5.0 (Android) LecteurManga/4.1");String host=new URL(url).getHost();if(host.equals("sushiscan.net")||host.endsWith(".sushiscan.net")){c.setRequestProperty("User-Agent",sourceAgent);String cookies=android.webkit.CookieManager.getInstance().getCookie(url);if(cookies!=null&&!cookies.isEmpty())c.setRequestProperty("Cookie",cookies);}
 c.setRequestProperty("Referer",(host.equals("sushiscan.net")||host.endsWith(".sushiscan.net")?SushiCatalog.BASE:Catalog.BASE)+"/");return c;}
 String friendly(Exception e){if(e instanceof SocketTimeoutException)return "Connexion trop lente. Réessaie.";if(e instanceof UnknownHostException||e instanceof ConnectException)return "Pas de connexion. Retrouve tes chapitres dans Téléchargements.";String m=e.getMessage();if(m==null||m.startsWith("https:")||m.contains("anime-sama")||m.length()>180)return "Chargement impossible. Réessaie.";return m;}
 void fetchImage(String url,File dest,Task task)throws Exception{HttpURLConnection c=connection(url);File tmp=new File(dest.getPath()+".part");try{if(c.getResponseCode()!=200)throw new IOException("Une page est indisponible. Tu pourras reprendre le téléchargement.");String mime=c.getContentType();if(mime==null||!mime.toLowerCase(Locale.ROOT).startsWith("image/"))throw new IOException("La page reçue n'est pas une image.");long size=0;try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(tmp)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(task.cancel||Thread.currentThread().isInterrupted())throw new InterruptedIOException();size+=n;if(size>40L*1024*1024)throw new IOException("Cette page est trop volumineuse.");if(getFilesDir().getUsableSpace()<30L*1024*1024)throw new IOException("Espace de stockage insuffisant.");out.write(b,0,n);}out.getFD().sync();}if(!OfflineStore.validImage(tmp))throw new IOException("Image incomplète. Réessaie.");OfflineStore.move(tmp,dest);}finally{c.disconnect();tmp.delete();}}
}
